window.CAPTIONS = {"congrats": [[0.02, 1.54, "The season may be over,"], [1.54, 4.9, "but the game of life and leadership never ends."], [5.02, 9.62, "You've done the work and you've earned this moment."], [9.62, 11.94, "It's time to celebrate."], [11.94, 15.34, "Welcome to the Athleader Hall of Fame."], [15.34, 17.22, "You have everything you need."], [17.22, 18.9, "You've got this."], [18.9, 21.42, "Now, make it happen."]], "drill_l1": [[0.0, 6.0, "You're mid-task, focused and in rhythm. Your inbox is full,"], [6.0, 9.8, "but you are on track with your to-do list,"], [9.8, 11.9, "and in the background someone is waiting on you."], [11.9, 16.3, "Then suddenly, something you were counting on just fell through."], [17.2, 21.5, "Before you do anything, what is the first thing you notice?"], [21.5, 25.5, "In your body? In your thoughts? What feelings do you have?"], [25.5, 28.3, "Do you have an urge to do something?"], [34.3, 39.5, "There's no right answer to what you just noticed."], [39.5, 41.4, "Don't change it. Just catch it."], [41.4, 46.5, "What you noticed is data. The signal your system sends when the unexpected happens,"], [46.5, 50.4, "before you've decided to do anything."], [51.0, 57.1, "For the rest of the season, every time something falls through, try to catch that signal before you act on it."], [57.1, 65.5, "There is nothing to fix yet. Just become aware."]], "drill_l2": [[0.0, 5.8, "You've been working intently on a critical project for a while now."], [5.8, 10.3, "It's organized, thoughtful, and strategically aligned."], [10.3, 14.2, "People are counting on the current version."], [14.2, 17.6, "However, you just got news."], [17.6, 19.9, "The plans have changed."], [19.9, 27.4, "What you built for the last few months is no longer the priority."], [27.4, 33.6, "Before you respond, what do you notice? In your body, in your thoughts,"], [33.6, 37.4, "your feelings, and your urge to act?"], [48.5, 51.9, "Whatever you're noticing isn't wrong."], [51.9, 55.8, "It's your system's opening move under change."], [55.8, 60.0, "The conditioning is choosing your next move on purpose,"], [60.0, 64.2, "instead of letting your immediate instinct choose for you."], [65.1, 69.2, "A. Push back and defend the original plan."], [69.25, 74.75, "B. Quietly absorb it and adjust on your own."], [74.85, 79.75, "C. Go straight to the people affected and rebuild together."], [79.85, 84.0, "D. Pause and ask questions before reacting."], [89.2, 95.0, "Same pressure one more time, but try the option you didn't pick."], [104.05, 107.8, "You just practiced the option that isn't automatic yet."], [108.3, 112.9, "That's what conditioning feels like before the moment demands it."]], "drill_l3": [[0.36, 3.16, "You have to make an important decision."], [3.16, 9.76, "Four pieces of new information arrive, one at a time, then nothing more comes."], [16.6, 21.5, "This is all the information you're going to get, and the decision is due now."], [21.5, 23.9, "What do you notice right away?"], [23.9, 28.0, "The pull to wait, the urge to move, something else?"], [44.7, 49.8, "How much certainty do you need before you're willing to move?"], [49.8, 52.6, "Most people never test that level."], [52.6, 56.4, "You're about to find out what yours is."], [56.4, 58.5, "Here are your options."], [58.5, 61.1, "Act with what you know."], [61.1, 66.1, "Ask for one more missing input that matters most."], [66.1, 68.9, "Push the decision to someone else."], [68.9, 70.9, "Wait for more certainty."], [86.3, 93.5, "Now, new decision, same amount of information as before, four pieces of six."], [93.5, 95.5, "What do you do this time?"], [106.6, 112.4, "You just tested your comfort zone and change in one sitting."], [112.4, 118.2, "This week, notice one real decision where you're waiting for more certainty than you actually need,"], [118.2, 123.6, "and practice taking action with incomplete information."]], "drill_l4": [[0.45, 3.73, "Something didn't go the way you hoped for."], [3.73, 8.0, "To keep it real, it didn't work."], [8.0, 13.45, "You have something else that needs your full attention, and it's in 15 minutes."], [13.45, 19.1, "Before you decide what to do next, what is still with you from what just happened?"], [19.1, 21.3, "Name it, even if briefly."], [36.45, 41.9, "How long does the last moment control the next one?"], [41.9, 44.3, "That's reset speed."], [44.3, 49.3, "And like an athlete's recovery between reps, it can be conditioned."], [49.3, 51.25, "Here are your options."], [51.25, 54.2, "Delay or cancel what's next."], [54.2, 57.4, "Show up and act like nothing happened."], [57.4, 61.1, "Show up, name it briefly and move forward."], [61.1, 64.8, "Show up and let the frustration spill into it."], [75.8, 80.7, "One more thing just went wrong, right on top of this."], [80.7, 82.05, "What do you do now?"], [87.95, 89.7, "Time yourself this week."], [89.7, 98.7, "Take note: after something goes wrong, how long before you're fully present for the next thing on your plate?"], [98.7, 102.7, "Try to shorten the gap."]], "drill_l5": [[0.45, 3.95, "You've made the call."], [3.95, 9.3, "Someone you respect disagrees, strongly, and they're challenging your decision in front of other people."], [9.3, 12.7, "Before you respond, what do you notice?"], [13.2, 18.05, "In your body, your thoughts, your feelings. What is your urge?"], [26.0, 31.05, "Pressure changes when another person is involved."], [31.05, 33.85, "What is your first move? Options could be:"], [33.85, 36.2, "Defend the decision."], [36.2, 39.0, "Back away from your position."], [39.0, 43.4, "Ask them to explain what you're missing."], [43.4, 47.85, "Pause, and separate the disagreement from the person."], [55.65, 60.9, "Now, same disagreement. This time, respond without defending yourself"], [60.9, 63.75, "or abandoning your position."], [67.9, 73.9, "That's hard. And now you're conditioning alignment without commitment."], [74.15, 79.65, "This week, notice one moment when disagreement makes you want to defend,"], [79.65, 82.55, "withdraw, or immediately solve."], [82.55, 86.4, "Catch the urge, then choose your response."]], "drill_l6": [[0.0, 3.0, "You're in the middle of something that matters to you,"], [3.5, 8.0, "something you've been building towards across this whole experience."], [8.8, 11.2, "The plan just changed."], [11.9, 13.8, "You don't have the full picture just yet,"], [14.5, 17.3, "but the last thing you tried didn't work."], [17.9, 21.6, "A person you trust strongly disagrees with your call,"], [21.6, 25.4, "and you already have more on your plate than you know what to do with."], [25.9, 29.4, "And people are watching how you handle this."], [30.0, 33.4, "Before you rush to respond to any of it,"], [34.0, 36.6, "what do you notice right now?"], [47.1, 51.0, "This is what makes the real moments different."], [51.0, 54.8, "Pressure rarely arrives one variable at a time."], [54.8, 58.8, "For five lessons, you've practiced these pressures one at a time."], [58.8, 61.0, "Now they're happening together. Which one is pulling hardest on you?"], [61.0, 65.1, "It's not a verdict. It's the exact information this whole experience was built to surface."], [65.7, 67.0, "What do you think first?"], [67.6, 68.5, "How do you feel?"], [69.1, 70.2, "What do you decide?"], [70.9, 76.3, "How do you access your best decision in the moment of pressure and change?"], [88.3, 91.2, "While you're still responding,"], [91.2, 94.4, "one more piece of information changes things yet again."], [100.8, 105.6, "Six lessons ago, we asked you to notice your first response."], [106.4, 110.4, "Since then, you've practiced changing plans, moving with uncertainty,"], [110.4, 114.2, "recovering after a miss, and staying open in disagreements."], [114.7, 119.4, "That's the difference between knowing what good leadership looks like"], [119.4, 124.1, "and being able to access it when the conditions get hard."], [124.7, 127.1, "You've practiced the latter."]], "p1_1": [[0.0, 12.68, "Welcome, I am Melissa Dawn Simkins and I am honored to be your coach through this flagship"], [12.68, 16.14, "experience called the M.V.P. Accelerator."], [16.14, 21.78, "This locker room isn't just where athletes prepare, it's where leaders are conditioned."], [21.78, 28.14, "The M.V.P. Accelerator is built for moments like this, when the pressure is on and purpose"], [28.14, 30.98, "must speak louder than fear."], [30.98, 35.1, "Congratulations on making the commitment to invest in yourself."], [35.1, 38.74, "You've just stepped into the Athleadership arena."], [38.74, 41.62, "This isn't just another leadership course."], [41.62, 46.98, "This is a conditioning experience to lead through real world change."], [46.98, 52.3, "We're not here to simply train you on leadership skills that you already know."], [52.3, 59.34, "We are here to fundamentally condition your capacity to lead and perform under pressure"], [59.34, 63.38, "through change and with purpose and so much passion."], [63.38, 68.86, "Over this journey, you will embark on your own championship season."], [68.86, 79.34, "We'll challenge you to go beyond going through it, to actively grow through it."], [79.34, 83.54, "We'll do this by conditioning what we call the Core 4."], [83.54, 86.18, "These are the essential performance pillars."], [86.18, 89.22, "We strengthen and measure these leadership muscles."], [89.22, 93.3, "Agility to adapt in real time with confidence."], [93.3, 98.34, "Resilience to champion under pressure and rebound stronger."], [98.34, 102.98, "Alignment to your purpose and to execute with clarity."], [102.98, 108.86, "And wellbeing to protect your energy and sustain peak performance."], [108.86, 110.5, "This is A.R.A.W."], [110.5, 115.14, "It's a framework and it's the foundation of everything we do here."], [115.14, 118.26, "Today, this is your first lesson."], [118.26, 119.5, "We suit up."], [119.5, 122.1, "We enter the Athleadership arena."], [122.1, 127.86, "We'll lay out the game plan for your season, introduce you to your core conditioning tools,"], [127.86, 134.22, "and most importantly, we'll set the intention that will fuel your entire journey."], [134.22, 135.14, "Ready to get started?"]], "p1_2": [[0.0, 6.32, "Now, let's talk about the philosophy that powers this entire experience."], [6.32, 7.32, "Athleadership."], [7.32, 14.24, "It's where the mindset of an elite athlete meets the mastery of next-level leadership."], [14.24, 17.0, "You are in the Athleadership arena."], [17.0, 23.8, "And it is the space that we condition you with content, community, and analytics that"], [23.8, 27.04, "drive lifelong results."], [27.04, 32.44, "You see, elite athletes don't just show up on game day and hope for the best."], [32.44, 36.04, "They build mental muscle memory."], [36.04, 40.92, "They condition their bodies and mind through disciplined practice."], [40.92, 42.64, "They have a system."], [42.64, 45.62, "We believe the best leaders do the same."], [45.62, 50.44, "They lead from their core and play for impact."], [50.44, 62.84, "That's the power of athlete leadership rooted in neuroscience and performance psychology,"], [62.84, 66.48, "where mental conditioning meets purpose."], [66.48, 70.28, "This is where science meets soul."], [70.28, 72.48, "This is what we're here to do."], [72.48, 78.0, "Condition your leadership muscles so that when the pressure is on, you don't just endure."], [78.0, 80.04, "You excel."], [80.04, 84.08, "And if you've never seen yourself as an athlete, it's okay."], [84.08, 88.0, "This isn't about playing sports, running fast, or lifting weights."], [88.0, 93.44, "It's about unlocking the discipline, the mental clarity, and the inner strength already in"], [93.44, 96.22, "you to win from within."], [96.22, 102.12, "Your championship season is built around a powerful foundational framework we call the"], [102.12, 104.12, "M.V.P. blueprint."], [104.12, 109.76, "M.V.P. stands for your mission, your vision, and your purpose."], [109.8, 116.68, "A significant challenge in leadership is that fewer than 20% of leaders have a strong sense"], [116.68, 119.12, "of their individual purpose."], [119.12, 125.08, "But for the 10% who actually do, it becomes their greatest advantage."], [125.08, 129.8, "The M.V.P. framework is your foundation for forever."], [129.8, 137.08, "I can tell you from my own journey, the moment I felt a drift, it's where the moment I lost"], [137.08, 139.88, "sight of my own M.V.P."], [139.88, 146.04, "The journey back to it is what turned pain into purpose, and it's what built a foundation"], [146.04, 149.72, "of winning in every area of my life."], [149.72, 156.08, "Your M.V.P. blueprint is that engine, and the Core 4 muscles, sometimes we refer to them"], [156.08, 161.4, "as the A.R.A.W. framework, are the wheels that drive you forward."], [161.4, 169.96, "Through this season, every drill, every reflection, is designed to strengthen these four key areas,"], [169.96, 172.36, "which are more than competencies."], [172.36, 177.2, "They are character building in real time and in real life."], [177.2, 178.48, "Why?"], [178.48, 181.88, "Because the test of leadership is not in comfort."], [181.88, 187.08, "It's in times of uncertainty, pressure, and change."], [187.08, 190.44, "So how do we translate this into real world results?"], [190.48, 194.04, "Through a system we call the 90-Day Way."], [194.04, 199.12, "This is your personal operating system that will not only get you through this program,"], [199.12, 205.04, "but will serve you season after season in every area of your life."], [205.04, 211.24, "Research suggests that 92% of people who set goals fail to achieve them."], [211.24, 215.12, "The difference isn't the goal, it's the system."], [215.12, 223.32, "The 90-Day Way provides a structure to set clear, meaningful goals tied to your M.V.P. blueprint."], [223.32, 229.76, "Take consistent action and build unstoppable momentum one 90-day season at a time."], [229.76, 235.04, "We'll dive deep into this further into your experience, but today I want you to know that"], [235.04, 241.48, "this is a system that will turn your intention into undeniable impact and make you a part"], [241.48, 246.28, "of the new league of leaders, the 10% who actually do."], [246.28, 252.12, "To guide you through this process, you have an essential toolkit, your M.V.P. playbook."], [252.12, 254.88, "Now this isn't just a companion workbook."], [254.88, 256.36, "It is the work."], [256.36, 260.48, "It is your sacred space for conditioning."], [260.48, 265.76, "Inside your playbook, you'll find the A.R.A.W. conditioning drills, the worksheets to architect"], [265.76, 273.12, "your M.V.P. blueprint and your 90-Day Way core scorecard to track your progress."], [273.12, 279.32, "It's where you'll do the reps, the reflection of the plays and design your next bold move."], [279.32, 283.6, "I encourage you to download your playbook now before you move on."], [283.6, 285.28, "Take a moment to look through it."], [285.28, 288.08, "Familiarize yourself with the layout."], [288.08, 292.36, "This is your personal training ground for the entire season."], [292.36, 297.6, "On it, you'll find your first drill, setting your why for this season."], [297.6, 299.52, "This isn't just a task."], [299.52, 301.52, "It's your commitment."], [301.52, 304.24, "It's your first step to owning your journey."]], "p1_3": [[0.0, 4.84, "You've taken the first step, and most important step, you showed up."], [4.84, 7.12, "You've entered the arena."], [7.12, 10.92, "The path ahead will be challenging."], [10.92, 14.28, "It will also be profoundly rewarding."], [14.28, 18.92, "Commit the time in advance on your calendar each and every week."], [18.92, 25.44, "The power to architect a career and life of extraordinary impact is not just a dream,"], [25.44, 35.72, "it's a capacity you can build, refine, and master."], [35.72, 41.52, "In our next lesson, we begin our preseason conditioning, where you'll start the deep"], [41.52, 47.68, "work of crafting your inner blueprint, the foundation of your leadership and your life."], [47.68, 52.36, "I am genuinely thrilled and honored to be your coach on this journey."], [52.44, 55.76, "I see the champion you are ready to unleash within."], [55.76, 57.24, "You've got this."], [57.24, 59.32, "Now make it happen."], [59.32, 62.79, "When you're ready, head to your playbook to complete your first drill."], [63.31, 65.47, "You're building the foundation."], [65.47, 66.47, "Keep going."]], "p2_1": [[0.0, 10.96, "Welcome back to the Athleadership Arena."], [10.96, 18.08, "In our first lesson, you suited up to commit to your championship season."], [18.08, 26.08, "Today, we begin what every elite athlete undergoes before they ever step onto the field."], [26.08, 28.72, "Pre-season conditioning."], [28.72, 30.68, "This isn't about running laps."], [30.68, 34.26, "This is about deep inner work."], [34.26, 41.28, "Think of it as your rear-view mirror, a moment, a chance to look back, take the lessons from"], [41.28, 45.48, "your life's journey, and make meaning from them."], [45.48, 51.88, "Before you begin to build a game plan for your future, you need a clear and honest scatter"], [51.88, 53.92, "report of yourself."], [53.92, 56.68, "We call this your inner blueprint."], [56.68, 63.56, "It's the unique combination of your values, your strengths, your life experiences, and"], [63.56, 65.64, "your energy patterns."], [65.64, 71.96, "The primary A.R.A.W. muscles we are conditioning in this lesson are your wellbeing through"], [71.96, 78.16, "deep self-awareness and your resilience by learning from your past."], [78.16, 84.46, "In a world where change is constant, this is your inner and anchor core."], [84.46, 90.18, "The stronger your inner blueprint, the more agile you can become in uncertainty."], [90.18, 96.66, "This lesson is about giving yourself the room to gather the essential raw materials."], [96.66, 102.42, "This is what you'll need to architect your M.V.P. blueprint in our next lesson."]], "p2_2": [[0.0, 7.76, "Let's start with the foundation of your inner blueprint, your core values."], [7.76, 12.32, "Think of your values as your personal true North Star."], [12.32, 18.44, "But what happens when the true North Star is put to the test?"], [18.44, 24.16, "There was a time I looked really good on paper, like I was winning."], [24.16, 28.08, "But honestly, I was running on fumes."], [28.08, 35.64, "I was pushing towards my goals to grow my family and my business, driven by my value"], [35.64, 37.28, "of faith."], [37.28, 45.52, "But my body was fighting an undeniable disease, and I had to make a hard decision."], [45.52, 48.84, "That moment taught me a critical lesson."], [48.84, 50.84, "That wasn't failure."], [50.84, 52.96, "That was feedback."], [52.96, 59.36, "And the real breakthrough wasn't in pushing through, but in choosing to have surgery"], [59.36, 61.04, "and recover."], [61.04, 68.4, "It was in that journey of transformation that I truly understood that rest isn't weakness."], [68.4, 70.36, "It's required."], [70.36, 77.6, "That's when values like wellbeing and resilience became powerful muscles that can redirect"], [77.6, 82.24, "your North Star and redefine what truly success looks like."], [82.72, 84.4, "What it means to win."], [84.4, 89.04, "In fact, it's how the Athleadership movement was born."], [89.04, 94.96, "When your daily actions are aligned with your deepest values, you experience a sense of"], [94.96, 97.84, "fulfillment and integrity."], [97.84, 100.0, "It just feels right."], [100.0, 105.36, "But when there's a disconnect, when you're asked to do something at work or in life that"], [105.36, 109.24, "clashes with your core values, you feel it."], [109.24, 114.76, "It's that sense of friction, of burnout, and of being out of sync."], [114.76, 118.68, "An Athleader knows that this alignment is not a luxury."], [118.68, 121.6, "It's a competitive advantage."], [121.6, 126.64, "It allows you to make hard decisions faster and with more confidence."], [132.24, 138.76, "For example, if your family is a core value, it gives you the clarity to turn down a promotion"], [138.76, 141.12, "requiring constant travel."], [141.12, 147.2, "If innovation is your core value, it gives you the courage to challenge the status quo,"], [147.2, 150.08, "even when it's uncomfortable."], [150.08, 155.32, "In your playbook, we're going to guide you through a drill to move beyond a long list"], [155.32, 162.4, "of nice sounding words to get crystal clear on the three to five values that truly define"], [162.4, 163.4, "you."], [163.4, 167.88, "The reason we focus on just a few is that it forces clarity."], [167.96, 172.0, "Having 20 values is the same as having none."], [172.0, 177.92, "But knowing your three to five, that's a powerful decision making filter."], [177.92, 182.2, "Remember, this isn't about what you think your values should be."], [182.2, 186.88, "It's about uncovering what they already are."], [186.88, 189.12, "Take your time with this."], [189.12, 193.28, "This clarity will become the bedrock of your M.V.P. blueprint."]], "p2_3": [[0.0, 8.64, "Next, let's talk about your strengths, and I want to make a critical distinction here."], [8.64, 11.72, "A strength isn't just something you're good at."], [11.72, 18.04, "You might be excellent at creating complex spreadsheets, but if the process drains every"], [18.04, 23.32, "ounce of energy, that's a learned skill, not a true strength."], [23.32, 26.28, "A strength is your natural advantage."], [26.28, 31.72, "It's an activity that you not only do well, but it also energizes you."], [31.72, 36.88, "It makes you feel authentic and creative and in a state of flow."], [36.88, 41.52, "Too often, our development plans are about fixing our weaknesses."], [41.52, 44.08, "An athlete flips that script."], [44.08, 47.6, "They focus on mastering and deploying their strengths."], [47.6, 54.12, "They find roles and projects where they can operate from their zone of genius as often"], [54.12, 55.7, "as possible."], [55.7, 60.64, "This is the fastest path to excellence and impact."], [60.64, 64.38, "We know you may have heard about focusing on strengths before."], [64.38, 70.78, "The difference in this experience is that we connect your strengths to your energy."], [70.78, 73.94, "An athlete doesn't just do what they're good at."], [73.94, 79.58, "They build their work and life around things that make them feel the most alive."], [85.7, 94.9, "Your playbook has a drill designed to help you identify the unique talents and highest"], [94.9, 97.42, "value that you bring to the table."], [97.42, 102.06, "Things that when you do them, you feel most alive and most powerful."]], "p2_4": [[0.64, 7.28, "The third element of your inner blueprint is your energy. And make no mistake, energy,"], [7.28, 14.56, "not time, is your most valuable currency for high performance. You can't create more time in the day,"], [14.56, 19.44, "but you absolutely can generate and protect more energy."], [20.16, 26.08, "Elite performers are masters of energy management. They are ruthless about identifying"], [26.08, 32.16, "what fuels them and what drains them. I want you to think about your own work this week."], [32.88, 37.44, "What are your drains? Maybe it's that two-hour status meeting that could have been an email."], [38.08, 42.96, "Maybe it's navigating the internal politics. Be honest. Name them."], [44.0, 50.24, "Now, what are your fuels? Maybe it's that 30-minute one-on-one conversation where you get to mentor"], [50.24, 58.0, "a junior colleague. Maybe it's that hour of deep, uninterrupted creative work. What activities make"], [58.0, 65.68, "you lose track of the time in the best way? Understand your personal energy cycles is critical"], [65.68, 72.4, "for sustainable success and is a core component of your wellbeing. The next activity in your"], [72.4, 79.6, "playbook will guide you through a personal energy audit. You'll identify the people, the task,"], [79.6, 86.0, "and the environments that either charge you up or deplete your reserves. This awareness"], [86.0, 96.96, "is the first step towards redesigning your day and your work for peak performance."]], "p2_5": [[0.0, 2.8, "Every great athlete, after a big game,"], [2.8, 5.32, "does one thing without fail."], [5.32, 7.58, "They review the game tape."], [7.58, 9.72, "They don't just do it to beat themselves up"], [9.72, 13.9, "over their mistakes, they do it to learn."], [13.9, 17.32, "They watch with their eyes like a coach,"], [17.32, 19.96, "objective and curious."], [19.96, 23.04, "Your life experiences are your game tape."], [23.04, 25.88, "The highs, the lows, the turning points,"], [25.88, 30.18, "they all contain powerful data about your passions,"], [30.18, 32.44, "what truly matters to you,"], [32.44, 35.64, "and especially your resilience."], [35.64, 39.96, "But let's be clear about what resilience means here."], [39.96, 43.06, "It isn't about how fast you bounce back,"], [43.06, 47.6, "it's about how fully you learn while you're down,"], [47.6, 52.12, "ensuring every comeback is smarter, not just stronger."], [52.12, 54.04, "In the final drill for this lesson,"], [54.08, 56.64, "we're going to prompt you to review your tape"], [56.64, 58.64, "with that lens."], [58.64, 62.28, "First, I want you to think about a specific moment"], [62.28, 67.28, "in your career when you felt truly alive and successful,"], [68.12, 70.26, "a peak performance moment."], [70.26, 71.92, "What was that project?"], [71.92, 74.72, "What was that specific role?"], [74.72, 78.06, "Now, success isn't always a straight line."], [78.06, 82.04, "Sometimes the most powerful parts of your success formula"], [82.04, 86.14, "are forged in moments that start with a no."], [87.28, 90.8, "I remember pitching my big idea to executives"], [90.8, 95.5, "at two NFL franchises and getting denied."], [95.5, 98.08, "I was disappointed, frustrated,"], [98.08, 101.2, "I felt inadequate and a little embarrassed,"], [101.2, 104.84, "but the mental muscle of resilience kicked in"], [104.84, 107.84, "and forged a new belief for me."], [107.84, 109.4, "I would say this,"], [109.4, 113.66, "I stand on a mountain of nos to get to one yes."], [114.56, 118.6, "Three years later, I got that yes."], [118.6, 122.92, "And a once rejected idea became the first ever"], [122.92, 127.06, "player brand university in professional sports."], [127.06, 129.92, "As you think about your peak performance,"], [129.92, 132.76, "don't just look at the final win,"], [132.76, 135.76, "look at the resilience it took to get there."], [136.64, 139.04, "That is your success formula."], [139.8, 142.48, "Then I want you to think about a time"], [142.48, 146.24, "when you faced a significant challenge or setback."], [146.24, 150.44, "We look back, not with judgment, but with curiosity."], [151.4, 153.16, "These key plays from your life"], [153.16, 155.76, "contain the final set of clues we need"], [155.76, 159.36, "to build your powerful M.V.P. blueprint."], [159.36, 163.2, "Resilience reveals what truly matters,"], [163.2, 168.08, "what sustains you and it tests what you've outgrown."], [168.08, 170.44, "Learning from your past gives you the tools"], [170.44, 172.8, "to lead through what's next."]], "p2_6": [[0.0, 5.04, "The work you do in your playbook for this lesson is foundational."], [5.04, 11.58, "The values, strengths, energy patterns, and life lessons you uncover are the raw materials"], [11.58, 20.64, "you will use in your next lesson to architect your M.V.P. blueprint."], [20.64, 23.76, "So don't rush this process."], [23.76, 30.28, "Give yourself space and grace to be honest and insightful."], [30.28, 36.96, "This self-discovery is the single most important investment you can make in your leadership."], [36.96, 43.08, "In the next lesson, we'll take everything you've uncovered and we will move into architecture"], [43.08, 49.68, "phase where we will build your mission, your vision, and your purpose and introduce the"], [49.68, 53.58, "90-Day Way system to bring it all to life."], [53.58, 56.34, "This isn't just about knowing yourself."], [56.34, 62.16, "It's about building the inner conditioning that drives the outer performance to lead"], [62.16, 66.18, "through change when everything around you is uncertain."], [66.18, 71.46, "If nothing else, I hope from the stories I've shared with you, you see this."], [71.46, 74.06, "You don't build your blueprint."], [74.06, 76.06, "You become it."], [76.06, 79.12, "And in that becoming, you don't just lead under pressure."], [79.12, 82.18, "You rise because of it."], [82.18, 84.74, "This is where the real you shows up."], [84.74, 87.54, "That's where the leader you've always been lives."], [87.54, 92.26, "You're putting in the foundational work that champions are built on."], [92.26, 93.26, "Keep going."], [93.26, 94.74, "You've got this."], [94.74, 98.02, "Now make it happen."], [98.02, 101.38, "Head to your playbook to complete the drills for this lesson."], [101.38, 104.18, "And when you're done, mark the lesson complete."], [104.18, 106.34, "I'll see you back here in the arena."]], "p3_1": [[0.0, 13.48, "Welcome back to the arena. You've completed your preseason conditioning. You looked inward,"], [13.48, 20.2, "you gathered the intel, you created your inner blueprint. You now have the raw materials,"], [20.2, 28.0, "your values, your strengths, your key experiences. This will shape how you not only win from"], [28.0, 36.76, "within, but it will shape how you begin to show up to those around you. Now today we move from"], [36.76, 43.76, "reviewing the game tape to drafting the playbook. We'll take the intel from your personal scouting"], [43.76, 52.8, "report and use it to design the single most important tool for your leadership. Your M.V.P."], [53.8, 62.2, "blueprint, which stands for your mission, vision, purpose, and values. After you've architected your"], [62.2, 69.56, "M.V.P., I'm going to introduce you to the performance system that will bring it all to life, the 90-day"], [69.56, 76.8, "way. This isn't about writing a purpose statement for a slide deck. It's about building your"], [76.8, 84.68, "strategic operating system that scales your leadership. This lesson is about building your"], [84.68, 93.36, "game plan. The A.R.A.W. pillars we are conditioning today are alignment and agility. Let's get to work."]], "p3_2": [[0.0, 4.76, "What does a civil rights icon like Martin Luther King Jr.,"], [4.76, 8.5, "a tech visionary like Steve Jobs, and a media mogul"], [8.5, 11.2, "like Oprah Winfrey have in common?"], [11.2, 16.2, "They all operate from a clear and powerful purpose."], [16.7, 20.16, "Your purpose is your why."], [20.16, 23.38, "It's your fundamental reason for being."], [23.38, 25.14, "Separate from your job title,"], [25.14, 28.5, "it's the lasting impact you want to have."], [28.5, 30.7, "And it's what drives you to take action"], [30.7, 32.88, "when the work gets hard."], [32.88, 36.3, "And yet, according to Harvard Business Review,"], [36.3, 38.92, "fewer than 20% of leaders"], [38.92, 41.92, "have a strong written purpose statement,"], [41.92, 44.66, "and even fewer have written it down."], [44.66, 49.66, "But today, you join the elite 10%."], [50.26, 51.88, "But before we draft your own,"], [51.88, 56.58, "it's critical to understand what purpose truly is."], [56.58, 61.04, "Think of your purpose as your personal operating system."], [61.04, 65.96, "It's the underlying code that runs everything else,"], [65.96, 70.96, "your decisions, your actions, and your priorities."], [71.36, 75.56, "When the operating system is installed and running,"], [75.56, 78.86, "you get powerful upgrades."], [78.86, 83.48, "The first is the greater meaning in your life and work."], [83.48, 86.48, "As an added bonus, research has shown"], [86.48, 90.06, "that living your purpose can increase resiliency,"], [90.06, 93.46, "improve sleep, and even decrease the risk"], [93.46, 95.54, "of cardiac disease."], [95.54, 97.74, "But maybe the most powerful upgrade"], [97.74, 102.74, "is how this OS manages your most valuable resource, time."], [103.8, 106.5, "Your purpose acts as a compass,"], [106.5, 109.74, "guiding your time management towards a life"], [109.74, 113.7, "that is not only efficient, but also fulfilling."], [114.68, 117.94, "It's the difference between doing things correctly,"], [117.94, 122.6, "which is time management, and doing the right things,"], [122.6, 126.08, "which is purpose-driven leadership."], [131.6, 135.42, "For me, my purpose is to awaken people"], [135.42, 138.64, "to the power of purpose as a catalyst"], [138.64, 142.26, "for remarkable leadership and a fulfilled life."], [142.3, 146.62, "When this why hit me, I had lost everything"], [146.62, 150.4, "and struggled to keep this business alive."], [150.4, 155.4, "I would tell myself, this why is bigger than you, Melissa."], [155.58, 158.8, "Purpose can drive performance."], [158.8, 161.54, "You will go global, Melissa."], [161.54, 166.22, "And now, in over 26 countries and counting,"], [166.22, 170.68, "those words on my vision board were not fluff,"], [170.7, 174.74, "they were fuel, high octane, that is,"], [174.74, 179.66, "that eventually connected you and I in this very moment."], [179.66, 184.28, "Notice, I didn't say I'm a CEO or I'm a coach."], [184.28, 188.1, "It's the why behind everything that I do."], [188.1, 192.62, "Knowing this why allows me to play to my strengths"], [192.62, 196.62, "and clarify boundaries, ensuring I'm operating"], [196.62, 199.54, "at my highest contribution."], [199.56, 202.08, "A financial leader I know describes her purpose"], [202.08, 206.06, "as keeping my people from making short-sighted decisions"], [206.06, 208.98, "against their own self-interest."], [208.98, 212.24, "It's about protection and wisdom."], [212.24, 215.52, "A brilliant engineer I coached said his purpose"], [215.52, 217.72, "was to build elegant solutions"], [217.72, 221.56, "that makes complex things simple for people."], [221.56, 226.08, "It's about creating clarity in a world of noise."], [226.08, 228.68, "In a world of constant change and distraction,"], [228.7, 232.14, "your purpose is your anchor."], [232.14, 233.82, "It gives you stability."], [233.82, 238.82, "Having a clear purpose statement creates focus."], [239.02, 243.18, "It clarifies your choices and defines your priorities"], [243.18, 246.66, "and defines how you operate each and every day."], [246.66, 249.3, "When you're faced with two good opportunities,"], [249.3, 253.06, "your purpose statement is the tiebreaker."], [253.06, 256.54, "It tells you which path is truly yours."], [257.44, 259.8, "Now in your playbook, you'll find a drill"], [259.8, 262.76, "designed to help you draft your purpose statement."], [262.76, 265.32, "Use the notes from lessons two,"], [265.32, 268.8, "your values, the moments that moved you."], [268.8, 273.42, "This isn't about finding the perfect right words."], [274.36, 277.28, "It's about getting the first draft down."], [277.28, 279.24, "It's gotta feel authentic."], [279.24, 282.08, "It will take time and it's okay"], [282.08, 285.2, "to have multiple drafts in this process."], [285.2, 288.34, "Choose progress over perfection."]], "p3_3": [[0.64, 4.96, "If your purpose is your why, your vision is your where."], [8.4, 15.28, "Now, a common question we get is, do I need one M.V.P. blueprint for my personal life"], [15.28, 23.76, "and then another for my professional life? The answer is no. An athlete leads one integrated life."], [24.64, 31.92, "It's important to know that drafting this vision takes time and you should expect to have"], [31.92, 39.76, "several iterations. Don't aim for perfection. Aim for progress because when you get clear on your"], [39.76, 46.48, "vision and you're able to share it, it builds a powerful foundation of trust with your team."], [47.44, 53.84, "Your vision is the ability to look ahead and see with vivid detail the future you're working to"], [53.84, 62.08, "create. It's the destination of your leadership map. A vision isn't a vague dream like,"], [62.08, 69.12, "I want to be successful. It's a clear written declaration. A powerful vision is sensory."], [69.12, 75.28, "What do you see? What do you hear? Who is around you? How do you feel? For example,"], [75.28, 82.32, "a vision statement might be, in five years I will be leading a global team recognized as an expert"], [82.32, 89.84, "in sustainable technology while maintaining the flexibility of being fully present for my family."], [89.84, 98.08, "It's specific. It's aspirational. It provides daily motivation. When the day-to-day work gets"], [98.08, 106.16, "tough, when you face a setback, you can close your eyes and see the vision. It reminds you"], [106.16, 113.6, "of what you're fighting for. It's what helps an athlete push through that last painful mile of"], [113.6, 120.64, "that marathon. They aren't thinking about the pain. They're visualizing the final finish line."], [121.28, 127.44, "In your playbook, you will use the reflections you did in lesson two on your desire to feature"], [127.44, 134.72, "state to draft a powerful vision statement. Now, don't be afraid to dream big. An athlete's"], [134.72, 145.36, "vision should stretch them. It should pull you forward."]], "p3_4": [[0.0, 7.2, "So you have your why, your purpose, and your where, your vision, now we need your how."], [7.2, 9.24, "This is your mission."], [9.24, 16.36, "But before we build it, let's be clear about the risk of operating without an M.V.P. blueprint."], [16.36, 22.84, "Without it, leaders often feel adrift, making decisions that can lead to burnout, a lack"], [22.84, 25.54, "of focus, and stagnation."], [25.54, 28.56, "Your blueprint is the antidote."], [28.56, 33.86, "Your mission is how you activate your purpose and vision every single day."], [33.86, 39.68, "If your vision is the destination, your mission is a specific vehicle you'll drive, providing"], [39.68, 42.24, "essential clarity and direction."], [42.24, 47.44, "It's important to know that this mission can and should evolve as you grow."], [47.44, 52.52, "Think of it as your operational game plan, defining the work you will do to make your"], [52.52, 54.76, "vision a reality."], [54.76, 59.56, "A powerful mission statement often follows a simple template."], [59.56, 70.48, "I will action for audience by area of focus to desired result."], [70.48, 77.16, "For example, I will build for my team by implementing clear systems to create an environment of"], [77.16, 80.52, "clarity and high performance."], [80.52, 87.46, "Or I will advocate for emerging artists by leveraging my network to secure them galleries"], [87.46, 88.88, "and funding."], [88.88, 90.28, "It's active."], [90.28, 92.06, "It's clear."], [92.06, 95.2, "Your mission acts as a guardrail."], [95.2, 100.64, "In our busy lives, we're constantly presented with opportunities, requests, and distractions."], [100.64, 104.0, "A clear mission helps you filter them."], [104.0, 110.4, "When a new project or opportunity comes up, you can ask, does this align with my mission?"], [110.4, 117.84, "If the answer is no, it's a distraction, and you can say no with confidence."], [117.84, 123.32, "If yes, it's an opportunity, and you can say yes with conviction."], [123.32, 128.6, "Head to your playbook to complete the final part of your M.V.P. Blueprint by drafting your"], [128.6, 130.04, "mission statement."]], "p3_5": [[0.8, 3.66, "You have done the deep work."], [3.66, 8.26, "You have your first draft of your M.V.P. blueprint,"], [8.26, 12.9, "your performance operating system, your compass."], [12.9, 17.24, "But most people write a vision they'll never live."], [17.24, 18.08, "Why?"], [18.08, 21.56, "Because they don't have a system for execution."], [21.56, 24.4, "That's what the 90-Day Way provides."], [24.4, 27.42, "It's your personal performance system."], [27.42, 30.32, "If your M.V.P. blueprint is the compass,"], [30.32, 34.7, "the 90-Day Way is the vehicle to move you forward."], [34.7, 37.78, "It's what gives your blueprint legs."], [37.78, 41.94, "Without this system, your blueprint is just a philosophy."], [41.94, 45.12, "With it, it's unstoppable."], [45.12, 48.32, "So what makes the 90-Day Way so unique?"], [48.32, 52.96, "It's how the system intentionally aligns your M.V.P. blueprint"], [52.96, 57.26, "with both your personal and professional progress."], [57.26, 61.46, "This isn't just about your next career move."], [61.46, 66.46, "It's about building one integrated, fulfilled life."], [67.4, 69.92, "Now, why 90 days?"], [69.92, 73.12, "Because a year is too long to plan in detail"], [73.12, 75.34, "and too much can change."], [75.34, 79.18, "A week is too short to build real momentum."], [79.18, 83.66, "90 days is the perfect length for a season."], [83.66, 86.56, "It's long enough to achieve significant goals,"], [86.56, 90.6, "but short enough to stay focused and agile."], [90.6, 92.74, "Your primary tools for this system"], [92.74, 96.88, "is the 90-Day Way Core 4 Scorecard,"], [96.88, 99.0, "which you will find in your playbook."], [99.0, 103.4, "You are building your own customized leadership algorithm."], [103.4, 105.16, "And here's the secret."], [105.16, 107.64, "This isn't just about productivity."], [107.64, 110.36, "It's about sustainability."], [110.36, 113.36, "The 90-Day Way gives you a rhythm, a cycle,"], [113.36, 116.28, "a chance to sprint and recover."], [116.28, 119.56, "That's how we build momentum without burnout"], [119.56, 121.96, "because a champion doesn't just play hard."], [121.96, 124.5, "They rest strategically."], [124.5, 128.12, "This scorecard is where you will translate your big goals"], [128.12, 130.92, "into specific measurable actions"], [130.92, 133.74, "aligned with your A.R.A.W. pillars"], [133.74, 136.12, "and track your progress weekly."], [136.12, 137.76, "It's the accountability system"], [137.76, 140.74, "that ensures your M.V.P. blueprint"], [140.74, 142.78, "doesn't just sit on the shelf."], [142.78, 144.4, "It gets lived."]], "p3_6": [[0.0, 8.72, "Let's recap. Today, you moved from discovery to architecture. You took the powerful insights"], [8.72, 15.36, "about yourself and forged them into the first draft of your M.V.P. blueprint, your mission,"], [16.08, 23.28, "vision, and purpose. You were also introduced to the 90-Day Way, the operating system you will"], [23.28, 31.68, "use to execute that blueprint. This is a monumental step. Your homework is to continue"], [31.68, 39.04, "refining your M.V.P. statements in your playbook. Live with them. Put them on. See how they feel."], [39.76, 46.24, "They don't have to be perfect, but they need to feel true. Read them out loud. Does it sound"], [46.32, 53.04, "like you? This is an iterative process and anticipate several drafts before you anchor"], [53.04, 60.32, "in on your final draft. In our next lesson, we will begin to activate this plan. We'll talk"], [60.32, 66.56, "about conditioning your resilience and agility to overcome the resistance you will inevitably face"], [66.56, 74.64, "as you start to make bold moves. You have your game plan. Now it's time to prepare to execute."], [74.64, 80.48, "You've got this. Make it happen. When you completed the drills from lesson three"], [80.48, 94.48, "in your playbook, mark the lesson complete. Keep up the momentum. I'll see you soon."]], "p4_1": [[0.0, 8.0, "Welcome back to the"], [8.0, 12.0, "Athleadership Arena. You have done the foundational work."], [12.0, 16.0, "You've created your inner blueprint and"], [16.0, 20.0, "you've architected your M.V.P. and you have your"], [20.0, 24.0, "game plan. But as any great champion will tell you,"], [24.0, 28.0, "the plan is not the victory. The victory is in"], [28.0, 32.0, "the execution. This is where the game begins."], [32.0, 36.0, "This lesson is about moving from the strategy"], [36.0, 40.0, "session to the playing field. But you're not playing"], [40.0, 44.0, "alone. It's about activating your M.V.P. in your"], [44.0, 48.0, "daily decisions and seeing how those choices create"], [48.0, 52.0, "a ripple effect that impact your team, your manager,"], [52.0, 56.0, "your stakeholders, your entire organization's outcomes."], [56.0, 60.0, "It's about what happens when your plan meets reality,"], [60.0, 64.0, "when you're facing resistance, obstacles, and the unexpected."], [64.0, 68.0, "This is why the primary of A.R.A.W. muscles we're conditioning"], [68.0, 72.0, "today are resilience and agility."], [72.0, 76.0, "Resilience is more than your capacity to absorb pressure."], [76.0, 80.0, "It's about how you model sustainable culture"], [80.0, 84.0, "for your team, one that beats burnout. Agility"], [84.0, 88.0, "is your ability to adapt and pivot without losing"], [88.0, 92.0, "momentum. A strategic pivot guided by your M.V.P."], [92.0, 96.0, "doesn't show indecision. It communicates strength."], [96.0, 100.0, "These two muscles working together are what"], [100.0, 104.0, "separate good leaders from great ones."], [104.0, 108.0, "Today we put your blueprint into action."]], "p4_2": [[0.0, 6.22, "So, how do we take this M.V.P. Blueprint from a document into your playbook and make it"], [6.22, 10.68, "living, breathing, a part of your leadership operating system?"], [10.68, 14.86, "You start by using it as a decision filter."], [14.86, 20.1, "Every day, you're faced with a dozen choices."], [20.1, 25.42, "Without a clear filter, you often make these choices based on what's the loudest, what's"], [25.42, 30.38, "the most urgent, or what we think others expect of us."], [30.38, 34.86, "This is a recipe for burnout and reactive leadership."], [34.86, 39.94, "As athletes, using your M.V.P. is a strategic filter."], [39.94, 41.78, "Let me give you a real example."], [41.78, 47.74, "I coached a director, let's call her Anna, whose purpose statement was to champion emerging"], [47.74, 51.58, "talent and build the next generation of leaders."], [51.58, 56.86, "Her mission was to dedicate her time to mentorship and creating growth opportunities for her"], [56.86, 58.34, "team."], [58.34, 64.3, "One afternoon, her boss offered her a stretch assignment, a high-profile project analyzing"], [64.3, 66.1, "market data."], [66.1, 71.94, "But it was solitary work that would take her away from her team a full quarter."], [71.94, 79.82, "A year ago, she would have said yes instantly, but now she ran it through her M.V.P. filter."], [79.82, 85.1, "She asked, does this project align with my purpose of championing talent?"], [85.1, 88.3, "Does it support my mission of mentoring my team?"], [88.3, 91.22, "The answer was a clear no."], [91.22, 96.42, "So she went back to her boss and said, listen, I'm honored by the offer."], [96.42, 98.22, "It's a critical project."], [98.22, 104.78, "However, my core focus this quarter, as we discussed, is on developing my team to increase"], [104.78, 107.1, "our overall capacity."], [107.1, 110.02, "Should we delegate this to my rising star, David?"], [110.02, 115.14, "I will oversee it, and I will make sure that it will be a fantastic growth opportunity"], [115.14, 116.14, "for him."], [116.14, 117.14, "Hmm."], [117.14, 118.7, "Do you see what happened?"], [118.7, 120.18, "She didn't just say no."], [120.18, 124.34, "She used her M.V.P. to propose a powerful yes."], [124.34, 129.18, "She stayed true to her purpose, created a growth opportunity for her direct report,"], [129.18, 133.26, "and demonstrated strategic leadership to her boss."], [133.26, 137.22, "This is activating your M.V.P. in your playbook."], [137.22, 142.78, "You'll work through a scenario to practice using your own M.V.P. as a decision filter."]], "p4_3": [[0.0, 7.72, "As soon as you start living your M.V.P. and pursuing your 90-Day Way goals, I can promise you"], [7.72, 9.28, "one thing."], [9.28, 11.44, "You will face resistance."], [11.44, 13.44, "It's inevitable."], [13.44, 16.4, "Resistance isn't a sign that you're on the wrong path."], [16.4, 19.6, "It's proof that you're moving forward."], [19.6, 26.48, "Often, that resistance is in the friction created in the gap between others' expectations"], [26.48, 29.14, "and your own intentions."], [29.14, 35.5, "How you lead your team through that gap is a defining moment of leadership."], [35.5, 37.62, "Athletes don't see this as a roadblock."], [37.62, 45.76, "They see it as the weight in their leadership weight training, building mental muscle memory."], [45.76, 51.58, "Every time you push against your core, your purpose, you get stronger."], [51.58, 54.54, "This resistance comes in two forms."], [54.54, 57.74, "First, there is internal resistance."], [57.74, 64.14, "This is the voice of self-doubt, the imposter syndrome that whispers, who are you to do"], [64.14, 65.14, "this?"], [65.14, 71.98, "It's the comfort of your old habits fighting against the discomfort of the new ambitions."], [71.98, 78.42, "The key to overcoming this is to acknowledge the feelings without giving it authority."], [78.42, 80.64, "Your playbook has a drill on this."], [80.64, 85.98, "You will name the voice of your inner critic and you will arm yourself with a counter-statement"], [85.98, 88.42, "rooted in your purpose."], [88.42, 91.9, "Then, there is the external resistance."], [91.9, 98.74, "This comes from skeptical colleagues, limited resources, or organizational inertia."], [98.74, 103.38, "When you try to change things, the system often pushes back."], [103.38, 107.46, "This is where resilience muscle is critical."], [107.46, 112.74, "One of the most powerful resilience tactics here is reframing."], [112.74, 115.06, "Let me make this personal."], [115.1, 121.78, "Early in my career, I pitched a new initiative and the division leader told me no."], [121.78, 127.86, "It would have been easy for me to see it as an obstacle and their no as a final rejection."], [127.86, 130.94, "But instead, I chose to reframe it."], [130.94, 138.34, "I reframed that skeptical executive not as a roadblock, but as a stress test for my idea."], [138.34, 144.66, "Their tough questions forced me to make a proposal that was stronger and bulletproof."], [144.66, 151.38, "I reframed their no not as rejection, but as a not yet, an opportunity to gather more"], [151.38, 155.06, "data and refine my approach."], [155.06, 160.78, "That mental shift from obstacle to opportunity is the core athlete's skill."]], "p4_4": [[0.0, 4.84, "The second muscle we condition is agility."], [4.84, 10.96, "No game plan, no matter how brilliant, survives first contact with reality."], [10.96, 16.36, "Your 90-day plan is a roadmap, not a rigid set of tracks."], [16.36, 19.08, "Agility isn't about having a perfect plan."], [19.08, 26.68, "It's about being masterful at adapting to the plan without losing sight of the destination."], [26.68, 30.44, "Think about a marketing team that launches a major campaign."], [30.44, 34.18, "The initial data comes back, it's a flop."], [34.18, 39.0, "An agile leader doesn't see failure, they see feedback."], [39.0, 43.9, "They notice an unexpected surge of interest from a different demographic on a different"], [43.9, 45.64, "platform."], [45.64, 48.96, "Instead of sticking to the original plan, they pivot fast."], [48.96, 55.34, "They reallocate resources to capitalize on the surprise opportunity, turning a potential"], [55.34, 58.7, "loss into a huge win."], [58.7, 61.5, "That is agility in action."], [61.5, 67.34, "The best way to build this kind of agility is to anticipate the need to pivot before"], [67.34, 69.42, "it even happens."], [69.42, 74.94, "In your playbook, you'll find a drill called stress testing your goals."], [74.94, 80.54, "You'll look at your 90-day plan and ask, where is this most likely to break?"], [80.54, 82.22, "What's the weakest link?"], [82.22, 88.58, "Identifying potential points of failure ahead of time can pre-plan your pivots."], [88.58, 92.54, "It's like a pivot practicing in a simulator."], [92.54, 97.06, "When the real thing happens, they don't panic, they execute."], [97.06, 101.14, "This proactive agility is the hallmark of an athlete."]], "p4_5": [[0.0, 7.48, "Activation is not a one-time event, it's a daily practice, it's the conscious choice"], [7.48, 13.34, "to filter your decisions through your M.V.P., it's the courage to embrace resistance as"], [13.34, 21.04, "training ground for your resilience and the wisdom to proactively plan to build your agility."], [21.04, 27.34, "Your playbook for this lesson is filled with drills to help you put this concept into practice."], [27.34, 32.9, "Take the time to work through the scenarios and stress test your own goals."], [32.9, 36.98, "This is how you move from knowing to doing."], [36.98, 43.06, "In our next lesson, we will focus on how to sustain the momentum, focusing on the critical"], [43.06, 45.78, "or A.R.A.W. pillar of wellbeing."], [45.78, 48.94, "You have your blueprint and your game plan."], [48.94, 50.66, "You are in the game."], [50.66, 51.66, "You're ready."], [51.66, 52.66, "You've got this."], [52.66, 55.38, "Now, make it happen."], [55.38, 58.66, "Head to your playbook and you'll see the next briefing."]], "p5_1": [[0.0, 10.08, "Welcome back to the arena."], [10.08, 17.24, "So far in this season, you have done the deep work of discovery to create your inner blueprint."], [17.24, 23.76, "You have architected your M.V.P. and you've started to activate it in the real world, conditioning"], [23.76, 26.56, "your resilience and agility."], [26.56, 34.32, "Now we arrive at a pivotal moment where strategy meets action in the most structured way possible."], [34.32, 40.6, "This lesson is where we pull it all together and into a tool that we truly use to elevate"], [40.6, 45.68, "your performance, the 90-Day Way Personal Brand Action Plan."], [45.68, 52.92, "A study from Dominican University found that people who write down their goals are 42%"], [52.92, 55.16, "more likely to achieve them."], [55.16, 56.16, "Why?"], [56.16, 61.72, "Because the act of writing it down is the first step in creating a system."], [61.72, 63.92, "It's not just about setting goals."], [63.92, 69.08, "It's about having a system to achieve them consistently."], [69.08, 71.96, "This is what the 90-Day Way provides."], [71.96, 78.16, "Today we will explore the prerequisites for your success, show you how to identify and"], [78.16, 85.28, "address your most critical gaps, and then guide you step by step in building your first"], [85.28, 87.0, "90 Day Plan."], [87.0, 93.24, "The A.R.A.W. pillars we are conditioning are alignment and wellbeing, ensuring your plan is both"], [93.24, 95.92, "purposeful and sustainable."]], "p5_2": [[0.96, 4.3, "Before any team executes a complex play,"], [4.3, 7.38, "they ensure all the elements are in place."], [7.38, 11.36, "We need to do the same for your 90-day plan."], [11.36, 15.16, "This pre-game check isn't just about you."], [15.16, 17.32, "It's about ensuring alignment"], [17.32, 19.72, "and two other critical areas,"], [19.72, 23.8, "your key relationships and your organization."], [23.8, 25.52, "So let's start there."], [25.52, 28.56, "We'll look at what's required for you personally,"], [28.56, 31.8, "but we'll also ask how does your plan align"], [31.8, 36.08, "with your team's goals and your organization's priorities?"], [36.08, 38.58, "And do you have the relational alignment"], [38.58, 41.3, "with your manager and stakeholders"], [41.3, 44.52, "and their expectations to make it happen?"], [44.52, 47.24, "Now, don't worry about whether you have"], [47.24, 49.16, "all these pieces in place."], [49.16, 53.48, "Just think about what's required to succeed."], [53.48, 55.16, "For this pre-game check,"], [55.2, 58.56, "we will look at the prerequisites in two key areas,"], [58.56, 60.28, "your personal readiness"], [60.28, 64.04, "and your relational organizational alignment."], [64.04, 67.16, "First, personal readiness."], [67.16, 69.56, "This is your internal state."], [69.56, 71.44, "It includes your mindset,"], [71.44, 74.2, "the belief you can achieve your goals,"], [74.2, 76.76, "your motivation and your energy,"], [76.76, 81.36, "your specific skills, knowledge and credentials."], [81.36, 83.74, "But that's only half of the picture."], [83.74, 85.98, "The other half is your relational"], [85.98, 88.02, "and organizational alignment."], [88.02, 90.86, "This is how you show up as a leader."], [90.86, 93.54, "This includes your manager alignment,"], [93.54, 97.82, "peer collaboration, direct report relationships."], [97.82, 100.02, "Having both your personal readiness"], [100.02, 102.06, "and your relational alignment in place"], [102.06, 106.0, "is what truly prepares you for the game."], [106.0, 107.88, "Let me give you an example."], [107.88, 112.1, "I worked with Lynn, an attorney reentering the workplace"], [112.1, 115.58, "and becoming lead in-house counsel."], [115.58, 119.06, "Her success wasn't just about her personal skills."], [119.06, 123.94, "It was about creating a 360 degree alignment."], [123.94, 127.3, "First, she needed relational alignment at home,"], [127.3, 129.98, "getting on the same page with her spouse"], [129.98, 132.86, "and securing reliable childcare system"], [132.86, 135.74, "to help her in her new schedule."], [135.74, 139.64, "Then she established manager alignment at work."], [139.64, 142.16, "She and her new boss created a plan"], [142.16, 145.08, "with crystal clear priorities."], [145.08, 149.64, "Finally, that clarity cascaded to her new team."], [149.64, 152.12, "Guided by a shared purpose and mission,"], [152.12, 157.12, "they were all empowered to say no to low impact requests."], [157.36, 161.08, "This protected their time and focused their energy,"], [161.08, 164.08, "driving incredible efficiency."], [164.08, 167.88, "That is how alignment across your entire life"], [167.88, 170.76, "creates productivity that you need to handle"], [170.76, 173.6, "major moments of change."], [173.6, 175.84, "Understanding all of these prerequisites"], [175.84, 177.56, "didn't discourage her."], [177.56, 179.12, "It empowered her."], [179.12, 183.72, "It gave her a clear checklist of what she needed to work on."], [183.72, 187.08, "In your playbook, the first drill will guide you"], [187.08, 190.88, "through identifying the essential elements of success"], [190.88, 192.48, "for your own vision."], [192.48, 194.8, "This is your pregame check."]], "p5_3": [[0.8, 3.72, "Once you know what's required for success,"], [3.72, 7.56, "it's time for an honest self-assessment."], [7.56, 9.88, "This is how you identify the gap"], [9.88, 13.2, "between where you are and where you want to be."], [14.08, 16.6, "These gaps are not weaknesses."], [16.6, 18.9, "They are opportunities."], [18.9, 21.72, "They are specific areas you will target"], [21.72, 24.44, "in your 90-day plan."], [24.44, 28.12, "Looking back at Lynn, her self-assessment was clear."], [28.12, 30.34, "Mindset, check."], [30.34, 32.64, "Motivation, check."], [32.64, 35.16, "Legal experience, check."], [35.16, 38.94, "Her gaps were in managing people, managing budgets,"], [38.94, 41.2, "and up-to-date industry knowledge."], [41.2, 43.84, "So, her Make It Happen checklist"], [43.84, 47.02, "focused on closing those specific gaps."], [47.02, 49.68, "These became her goals."], [49.68, 53.08, "But a goal like getting better at managing budgets"], [53.08, 54.56, "is not a goal."], [54.56, 55.88, "It's a wish."], [55.88, 59.52, "To make it real, we use the SMART framework."], [59.52, 60.88, "Now, I know many of you say,"], [60.88, 63.24, "I've heard of the SMART goals before."], [63.24, 66.56, "But remember, this isn't about what you know"], [66.56, 67.88, "or what you've heard."], [67.88, 71.32, "It's about what you do daily."], [71.32, 75.5, "An Athleader applies these principles with discipline."], [75.5, 80.5, "Your goal must be specific, measurable, attainable,"], [80.5, 82.66, "relevant, and time-bound."], [82.66, 85.1, "Let's look at another example."], [85.1, 89.3, "Evan is a CFO and a father of a son with autism."], [89.3, 92.58, "His passion is to launch an online community"], [92.58, 96.54, "to support other parents of children with special needs."], [96.54, 98.94, "One of the items on his gap checklist"], [98.94, 102.1, "was identifying a technical partner."], [102.1, 105.88, "A SMART goal that became, within 60 days,"], [105.88, 110.88, "obtain partnership proposals from three qualified vendors"], [110.9, 114.94, "with each proposal detailing the creation"], [114.94, 118.94, "of a scalable online community that includes reporting,"], [118.94, 123.18, "functionality, and content self-management."], [123.18, 124.76, "Do you see the difference?"], [124.76, 127.64, "It's specific, it's measurable, it's attainable,"], [127.64, 132.52, "it's relevant to his vision, and it's time-bound."], [132.52, 135.48, "That is a goal you can execute against."], [135.48, 137.84, "In your playbook, you will assess yourself"], [137.84, 141.36, "against the prerequisites you've identified."], [141.4, 145.56, "Find your most critical gaps and then transform those gaps"], [145.56, 149.6, "into two or three powerful SMART goals"], [149.6, 152.38, "for your first 90-day season."]], "p5_4": [[0.84, 4.36, "Okay, you have your two to three SMART goals."], [4.36, 7.16, "Now we build the action plan."], [7.16, 12.16, "This is where you use your 90-Day Way Core 4 scorecard."], [12.16, 15.76, "The 90 day plan is rooted in your M.V.P. and values."], [15.76, 18.5, "It incorporates both your professional"], [18.5, 20.64, "and personal priorities."], [20.64, 23.48, "For each goal, your plan guides you"], [23.48, 26.8, "to ask four critical questions."], [26.8, 31.56, "First, what daily or weekly actions are required?"], [31.56, 34.88, "Break the goal into concrete steps."], [34.88, 38.12, "Second, what resources are needed?"], [38.12, 41.6, "Is it time, money, introductions,"], [41.6, 44.32, "a specific piece of information?"], [44.32, 47.84, "Third, who is in your corner?"], [47.84, 50.32, "An athlete does not train alone."], [50.32, 53.6, "They build an ecosystem of accountability."], [53.6, 58.6, "This requires creating alignment on multiple fronts."], [58.86, 63.32, "With your manager, what conversations do you need to have"], [63.32, 66.2, "to get their support and buy in?"], [66.2, 69.44, "With your team, how will you communicate your goals"], [69.44, 72.0, "so they can support the vision?"], [72.0, 73.9, "And with your loved ones at home,"], [73.9, 75.6, "what do they need to know"], [75.6, 78.68, "to be a part of your support system?"], [78.68, 81.1, "Think about the right cadence for check-ins"], [81.1, 84.5, "with each of these groups to keep them engaged,"], [84.5, 87.5, "but also to keep yourself on track."], [87.5, 90.78, "And finally, what is the deadline?"], [90.78, 92.5, "How will you celebrate?"], [92.5, 95.34, "Deadlines drive execution."], [95.34, 99.68, "And celebrating as an outcome, even if it's a small win,"], [99.68, 102.28, "is what builds the positive momentum"], [102.28, 105.78, "that makes you want to tackle the next goal."], [105.78, 110.52, "It's a crucial part of your wellbeing and resilience."], [110.52, 113.32, "This plan is a living document."], [113.32, 114.58, "It's flexible."], [114.58, 117.96, "It gives you direction, but it also allows you to pivot"], [117.96, 120.52, "when the unexpected happens."], [120.52, 123.08, "In your playbook, you'll use the template"], [123.08, 126.06, "to build out your first 90-day plan"], [126.06, 128.08, "for each of your SMART goals."], [128.08, 132.02, "This is your roadmap for the next three months."]], "p5_5": [[0.0, 9.0, "Using this 90-day action plan accelerated my personal brand success and it clarified what truly mattered."], [9.0, 14.0, "It guided me on how to be intentional about building the life that I want."], [14.0, 23.0, "It's been a powerful resource for me and for thousands of leaders around the world, and I'm so excited to see it work for you."], [23.0, 29.0, "You have done the work. You have a plan that's rooted in purpose and designed for action."], [29.0, 32.0, "This is a massive accomplishment."], [32.0, 44.0, "In our final lesson, we will focus on the victory lap, how to integrate all of your learnings, celebrate your progress, and prepare for your next championship season."], [44.0, 51.0, "You are in the heart of this season. This is where champions are made. You've got this."], [51.0, 53.0, "Now, make it happen."], [53.0, 59.0, "Head to the playbook to complete the drills, and I'll see you for the final lesson."]], "p6_1": [[0.0, 11.4, "Welcome back to the arena for your final lesson."], [11.4, 19.3, "I want you to take a deep breath and a moment to acknowledge where you are."], [19.3, 20.5, "You made it."], [20.5, 26.02, "You stayed the course through a rigorous experience and you did the work."], [26.02, 31.02, "On behalf of myself and the entire Velvet Suite team, congratulations."], [31.02, 32.82, "You did it."], [32.82, 35.5, "Today is your victory lap."], [35.5, 40.62, "It's a moment to celebrate your progress, to consolidate the powerful lessons you've"], [40.62, 44.42, "learned and to honor the leader you have become."], [44.42, 50.7, "But in the world of Athleadership, the final whistle of one season is also the starting"], [50.7, 53.02, "pistol for the next."], [53.02, 57.78, "The work of a champion is never truly done, it just evolves."], [57.78, 63.1, "So this lesson is also about your post-season review."], [63.1, 68.7, "We will reflect on your journey, integrate your learning so they become a permanent part"], [68.7, 75.98, "of your leadership DNA and create a clear plan for your next 90-day season."], [75.98, 82.92, "The A.R.A.W. focus today is on a full integration of all four of our pillars, preparing you"], [82.92, 86.4, "to carry this momentum forward indefinitely."], [86.4, 88.88, "Let's take our final lap together."]], "p6_2": [[0.8, 3.24, "I want you to think back to who you were"], [3.24, 6.48, "when you started this journey in lesson one."], [6.48, 8.64, "Think about the intention you set"], [8.64, 10.96, "and the goals you articulated."], [10.96, 14.56, "Now think about where you are today."], [14.56, 16.88, "The growth that has happened in a season"], [16.88, 20.62, "of focused conditioning is profound."], [20.62, 23.0, "The best way to solidify that growth"], [23.0, 26.08, "is to review your game tape."], [26.08, 29.0, "In your playbook, you'll find the final section"], [29.0, 31.28, "of your 90-Day Way scorecard."], [31.28, 35.16, "It's your personal post-season review."], [35.16, 38.6, "It's going to prompt you to identify your biggest wins"], [38.6, 41.24, "and your most significant breakthroughs"], [41.24, 44.32, "across each of the A.R.A.W. pillars."], [44.32, 48.32, "Don't rush this, be specific."], [48.32, 51.04, "What was your biggest agility win?"], [51.04, 54.52, "Maybe it was a moment you had to pivot on a project"], [54.52, 57.06, "and you did it with confidence."], [57.1, 60.02, "When did your resilience shine through?"], [60.02, 62.7, "Think of a specific moment you faced criticism"], [62.7, 65.14, "and instead of getting defensive,"], [65.14, 68.22, "you chose to lean in and be curious."], [68.22, 70.98, "What was your most important alignment breakthrough?"], [70.98, 73.86, "Was there a tough decision you had to make"], [73.86, 78.3, "and you did it because it didn't align with your M.V.P.?"], [78.3, 81.46, "What was your new wellbeing habit?"], [81.46, 85.54, "And maybe how did that make a difference in your energy?"], [85.54, 89.58, "Taking the time to name these wins is not about ego."], [89.58, 92.3, "It's about encoding the lessons."], [92.3, 95.18, "When you consciously acknowledge a breakthrough,"], [95.18, 96.86, "you're telling your brain,"], [96.86, 100.02, "this is a new strategy that works, hello."], [100.02, 102.74, "This is who I am now."], [102.74, 104.1, "Let's keep it."], [104.1, 106.66, "You are solidifying the neural pathways"], [106.66, 110.1, "to becoming the athlete you were always meant to be."]], "p6_3": [[0.64, 3.34, "Many people finish an experience like this"], [3.34, 5.0, "and feel a surge of motivation"], [5.0, 7.32, "and then they think in a few weeks"], [7.32, 8.58, "they're gonna keep moving forward"], [8.58, 10.52, "and then they realize the binder"], [10.52, 12.48, "and the notes go on the shelf"], [12.48, 15.2, "and old habits start to creep back in."], [15.2, 17.74, "That will not be your story."], [17.74, 18.98, "Why?"], [18.98, 20.64, "Because the M.V.P. Accelerator"], [20.64, 23.72, "is not a one and done training event."], [23.72, 24.68, "No, no, no."], [24.68, 27.8, "We didn't just give you information."], [27.84, 30.38, "We gave you an operating system."], [38.96, 41.7, "The 90-Day Way isn't a one time fix."], [41.7, 44.62, "It's your operating system for a lifetime"], [44.62, 48.72, "of peak performance and strategic recovery."], [49.7, 52.56, "It's a foundation you build upon forever,"], [52.56, 55.72, "starting fresh each season."], [55.72, 57.64, "The end of this 90 day plan"], [57.64, 60.08, "is simply the beginning of the next."], [60.08, 62.16, "You now have a proven system"], [62.16, 64.44, "for setting purposeful goals"], [64.44, 67.52, "and achieving them in manageable sprints"], [67.52, 71.4, "for the rest of your life and leadership."], [71.4, 73.0, "Think about that."], [73.0, 77.38, "You have a tool that you can use every single quarter"], [77.38, 79.62, "to ensure you are consistently"], [79.62, 83.34, "and intentionally moving towards your grand vision."], [83.34, 86.42, "The goal isn't just a complete one 90 day plan."], [86.42, 89.42, "It's to master the rhythm of the 90-Day Way."], [89.42, 90.82, "And let's be realistic."], [90.82, 94.34, "Some of your goals will take longer than 90 days"], [94.34, 96.3, "and delay will happen."], [96.3, 98.4, "The rhythm isn't about perfection."], [98.4, 102.58, "It's about persistent focused progress."], [102.58, 106.32, "Your M.V.P. blueprint is also a living document."], [106.32, 107.7, "The person you are today"], [107.7, 110.5, "is not the same person you will be in a year"], [110.5, 111.94, "or in five years."], [111.94, 113.38, "Your priorities will shift."], [113.38, 115.1, "Your wisdom will deepen."], [115.1, 118.18, "I encourage you to schedule time on your calendar,"], [118.18, 123.18, "maybe once or twice a year to revisit and refine your M.V.P."], [123.26, 125.42, "Does your purpose still ring true?"], [125.42, 127.38, "Has your vision evolved?"], [127.38, 129.82, "Does your mission need to adapt to a new role"], [129.82, 132.02, "or a new stage of life?"], [132.02, 134.86, "The document isn't meant to be static."], [134.86, 137.06, "It's meant to evolve with you."], [137.98, 142.14, "Athleadership is a commitment to continuous conditioning."], [142.14, 144.92, "It's the daily choice to lead with purpose,"], [144.92, 147.5, "to manage your energy, to stay agile"], [147.5, 150.0, "and to bounce back with resilience."], [150.0, 152.38, "The tools you gained in this experience"], [152.38, 154.94, "will serve you for a lifetime."], [154.94, 158.54, "But only if you continue to use them,"], [158.54, 162.54, "to sharpen them, to make them your own."], [162.54, 165.94, "This is your commitment to a career of impact"], [165.94, 167.74, "and a life of meaning."], [167.74, 172.06, "One that is clear, focused and sustainable."]], "p6_4": [[0.36, 1.92, "As we close this season,"], [1.92, 6.06, "I want to leave you with one final thought."], [6.06, 9.94, "The work you've done here, it's bigger than you."], [9.94, 12.42, "It's not just about getting your next promotion"], [12.42, 14.58, "or achieving personal goals."], [14.58, 17.58, "It's about legacy."], [17.58, 20.22, "The leader you have become through this process,"], [20.22, 23.1, "the leader who operates from a place of clarity,"], [23.1, 26.46, "of purpose, who champions their team with empathy,"], [26.46, 29.7, "who navigates change with grace and agility,"], [29.7, 34.38, "that leader has an impact on every person you touch."], [34.38, 37.48, "Your clarity gives your team clarity."], [37.48, 39.84, "Your resilience gives them strength."], [39.84, 43.36, "Your alignment inspires them to find their own."], [43.36, 46.8, "This is the ripple effect of authentic leadership."], [47.72, 48.88, "As you move forward,"], [48.88, 51.8, "I want you to think about this question."], [51.8, 55.5, "Who will benefit from the leader I have become?"], [56.5, 59.66, "Your M.V.P. isn't just a blueprint for your own success."], [59.66, 64.5, "It's a blueprint for the impact you will have on the world."], [65.34, 69.66, "And now we want you to share a piece of that impact."], [69.66, 72.54, "We invite you to our wall of fame"], [72.54, 77.54, "to tell us about a win or a key moment from this experience."], [77.94, 81.54, "Think about a specific before and after moment."], [81.54, 84.06, "How did you handle a challenge differently?"], [84.18, 86.14, "Did you make a different choice?"], [86.14, 89.86, "Did you see change in yourself or your team?"], [89.86, 94.3, "You see, your story of transformation is powerful."], [94.3, 97.3, "It's not only solidifying your journey,"], [97.3, 100.38, "but it also is inspiring the next wave of leaders"], [100.38, 102.42, "who will come after you."], [102.42, 104.4, "This is your legacy."]], "p6_5": [[0.72, 3.0, "Your final set of drills are waiting for you"], [3.0, 4.4, "in your playbook."], [4.4, 6.44, "They are designed to help you complete"], [6.44, 10.0, "your 90 day assessment and reset."], [10.0, 12.6, "Capturing your wins and setting your focus"], [12.6, 13.8, "for your next season."], [13.8, 15.48, "I also ask that you complete"], [15.48, 18.28, "your final post-course assessment."], [18.28, 20.96, "Your feedback is invaluable to us"], [20.96, 24.28, "to help us continue to make this experience powerful"], [24.28, 26.6, "for the athletes who will come after you."], [27.6, 31.64, "I am so incredibly proud of the work you've done."], [31.64, 33.72, "It has been my absolute honor"], [33.72, 36.0, "to be your coach on this journey."], [36.0, 37.8, "You've stepped into the arena,"], [37.8, 39.68, "you've faced the challenges,"], [39.68, 41.0, "you've put in the reps,"], [41.0, 43.2, "you have emerged stronger,"], [43.2, 45.76, "more focused and more aligned."], [45.76, 48.96, "You are now a member of a very special"], [48.96, 50.92, "community of athletes."], [50.92, 52.44, "The season may be over,"], [52.44, 55.8, "but the game of life and leadership never ends."], [55.92, 60.52, "You've done the work and you've earned this moment."], [60.52, 62.84, "It's time to celebrate."], [62.84, 66.24, "Welcome to the Athleader Hall of Fame."], [66.24, 68.12, "You have everything you need."], [68.12, 69.8, "You've got this."], [69.8, 72.32, "Now, make it happen."]], "pro_lachina": [[0.0, 14.18, "Hello, my name is Lachina Robinson and I'm a sports broadcaster for ESPN."], [14.18, 20.7, "I am so excited to be joining Melissa Dawn-Simkins and the Velvet Suite as a founding ambassador"], [20.7, 22.9, "for athleadership."], [22.9, 27.5, "You're probably wondering what a basketball analyst has in common with business leaders."], [28.2, 34.1, "When I say the word agility, I hope that resonates with you because it definitely resonates with"], [34.1, 36.74, "me and I will tell you how."], [36.74, 41.14, "As a basketball analyst, it is my job to be the expert on the broadcast."], [41.14, 47.02, "Leading up to a game, I spend countless hours watching film, interviewing players and coaches,"], [47.02, 52.62, "studying statistics, diving into the rules of the game, learning every aspect of the"], [52.62, 54.94, "entire event."], [54.94, 60.98, "My specific function as the color on the broadcast is to explain and analyze why things"], [60.98, 62.58, "are happening."], [62.58, 65.88, "Why does player A have 30 points?"], [65.88, 68.94, "Why is team B in a zone defense?"], [68.94, 72.2, "Why did coach A just call a timeout?"], [72.2, 75.46, "What does it mean when the officials call travel?"], [75.46, 81.18, "I am teaching by taking the viewer behind the veil into the minds of the players, coaches,"], [81.18, 87.26, "officials, even the fans, to explain why certain events are taking place and hopefully"], [87.26, 90.28, "make the game more enjoyable."], [90.28, 95.9, "The definition of agility is the ability to think and understand quickly."], [95.9, 101.14, "There are hundreds of thousands and sometimes millions of people watching a sporting event"], [101.14, 103.9, "on television at any given time."], [103.9, 109.86, "And it's my job to understand what is happening very quickly and to be able to communicate"], [109.86, 114.06, "that to the audience in the moment as it's happening."], [114.06, 119.42, "Talk about pressure, but you get it because it is essential that you are equipped with"], [119.42, 121.86, "this tool as a business leader."], [121.86, 127.46, "Let me give you an example of how agility comes into play in my day to day."], [127.46, 132.66, "In that high pressure situation with millions of viewers watching a game, I have prepared"], [132.66, 136.26, "for what I expect to happen in the game."], [137.26, 142.9, "Sure, nothing in sports ever happens the way we expect, but that doesn't change my role."], [142.9, 145.14, "And that is where agility comes in."], [145.14, 151.94, "As a leader, we can prepare for the moment and do the diligence required to be an expert,"], [151.94, 157.74, "but nothing can prepare you for the moment of having to change course under pressure."], [157.74, 163.22, "To communicate to an audience, to your staff, to those who follow your command that something"], [163.22, 171.26, "else is happening, something I didn't specifically prepare for, but I couldn't predict it."], [171.26, 180.26, "However, because I have trained, I know that I can find my way and make the changes necessary."], [180.26, 185.86, "Agility takes trust that as an expert, you prepared for a change of plans, that the unexpected"], [185.86, 190.66, "outcome or action isn't the end of your skill set or training."], [191.1, 199.18, "You don't know how your opponent will game plan for you, but you know that whatever that"], [199.18, 204.5, "looks like, you can think and understand quickly in order to adjust."], [204.5, 212.1, "You can be agile in reaching your goal, even if you get there in a different way than you expected."], [212.1, 216.38, "Being agile is critical in situations where you need to adjust."], [216.38, 220.12, "I hope this helps you in your journey as an athlete."], [220.12, 223.12, "You have everything you need."], [223.12, 228.4, "You have prepared, practiced, and now it's time to execute."], [228.4, 229.12, "Stay agile."]], "pro_mannino": [[0.0, 13.6, "Hi, everyone. I'm Dr. Michael Manino. There was a moment a few years back when I was leading"], [13.6, 19.92, "a high stakes cross-disciplinary project under a tight deadline with my team. And the stakes"], [19.92, 23.68, "weren't just about the outcome. They were about proving that our team could perform"], [23.68, 28.0, "under pressure. This would be a great example. We'd be setting a great precedent for our"], [28.0, 33.92, "team. We had talented people, but we weren't moving as one. We were working hard in parallel,"], [33.92, 38.96, "but we weren't truly connected. And under pressure, that misalignment starts to compound."], [38.96, 46.24, "Communication gets clipped, trust and psychological safety gets tested, decisions take longer. We"], [46.24, 52.0, "needed to get in sync, literally. Teams on the same wavelength literally performed better."], [52.88, 58.96, "And a study out of Dartmouth actually showed this. Researchers had teams watch silent,"], [58.96, 65.12, "confusing film clips and then discuss what they thought was happening. The most successful teams,"], [65.12, 70.88, "the ones whose brains literally synchronized during the discussions, had one thing in common,"], [70.88, 76.24, "a unique team member who fostered alignment. They weren't the loudest voiced in the room,"], [76.32, 81.92, "but they asked open-ended questions, reflected ideas back, adapted their tone to match the"], [81.92, 86.56, "groups, and they created a safe space for everybody to contribute. That communication"], [86.56, 92.72, "style created deep synchrony, shared understanding and group cohesion. Now, on my own team,"], [92.72, 98.48, "I shifted from pushing for answers to trying to create that space with that communication style."], [98.48, 103.68, "And almost immediately, I saw a shift in people's minds. We realigned on our mission,"], [103.68, 109.12, "clarified priorities, and agreed not just on what we were doing, but how we'd move together."], [109.12, 113.76, "That moment unlocked alignment. People started anticipating each other's needs,"], [113.76, 117.92, "recovering from mistakes instantly, and making faster and better decisions."], [118.88, 124.48, "It felt like team flow. That's an optimal state of consciousness, a collective state of mind where"], [124.48, 129.52, "the whole is greater than the sum of the parts and everything just clicks as if the team operates as"], [129.52, 135.12, "one unified organism with a collective ambition. Everybody's operating at their edge, but in sync."], [136.08, 142.64, "Now, alignment isn't just a one-time event. It's a living, breathing process. Under pressure,"], [142.64, 148.08, "it can fray fast, and agility is what keeps it alive. Alignment gives you direction,"], [148.08, 153.2, "and agility lets you adapt without losing it. And when you have both, you create the conditions for"], [153.2, 159.84, "team flow. The state where trust, communication, and performance all reinforce one another."], [160.72, 166.4, "Now, over the next 90 days, you'll face moments where pressure spikes. That's your cue to pause"], [166.4, 171.52, "and check. Are we still truly aligned? And can we pivot without losing that connection?"], [172.4, 177.04, "So here's my challenge to you. This week, take 20 minutes with your team and ask two questions."], [177.2, 183.36, "What are we really here to accomplish? And how will we move together when things change? How"], [183.36, 188.96, "will we get in sync? Answer honestly, and you'll be building the foundation for alignment, agility,"], [188.96, 191.44, "and team flow. Good luck."]], "pro_ryall": [[0.0, 15.72, "There was a time in my athletic career when my body and my mind hit rock bottom."], [15.72, 19.0, "I had battled a severe eating disorder."], [19.0, 24.76, "I had pushed through multiple burnouts and suffered severe sports injuries."], [24.76, 31.92, "On the outside, it looked like I was winning titles, magazine covers, accolades, traveling"], [31.92, 37.48, "the world with Arnold, but on the inside, I was crumbling."], [37.48, 43.4, "I was performing at an elite level without a foundation that could actually sustain me."], [43.4, 44.4, "You know what?"], [44.4, 49.56, "I didn't even realize how dangerous that was until my body forced me to stop."], [49.56, 52.16, "That was my wake-up call."], [52.16, 57.88, "I learned that resilience and wellbeing, these aren't just side projects."], [57.88, 62.96, "These are the main gain because when you lose your health, nothing else matters."], [62.96, 68.48, "The medals, the money, the milestones, the accolades."], [68.48, 72.88, "For you as leaders, the pressures may look different than mine as a professional athlete"], [72.88, 75.48, "on a competition stage, but they're really not."], [75.48, 77.44, "The demands are the same."], [77.44, 85.56, "Long hours, performance under pressure, high stakes, and the temptation is always there"], [85.56, 89.68, "to sacrifice our own wellbeing for results."], [89.68, 95.52, "The reality is, is peak performance without sustainable wellness, it's always going to"], [95.52, 98.12, "lead to a breaking point."], [98.12, 100.0, "When that happens, it doesn't just affect you."], [100.0, 104.36, "It affects your business, it affects your family, and it affects your legacy."], [105.32, 111.12, "So Wellness IQ, it's about conditioning yourself from the inside out."], [111.12, 115.64, "It's about creating a platform for sustainable wellness so that you can thrive in life and"], [115.64, 123.36, "you can lead with energy, with clarity, and with peace amongst pressure."], [123.36, 128.52, "So if you want to grow as a leader, you have to start by strengthening your foundation"], [128.52, 132.04, "that supports it all, your health and your wellbeing."], [132.08, 137.04, "And an important question I'd love for you to ask yourself is, if I continue at the same"], [137.04, 143.76, "pace I'm moving at now for the next 10 years, is that possible?"], [143.76, 146.68, "Will I still be thriving in 10 years?"], [146.68, 152.92, "And if that answer isn't a confident yes, it's time to do things differently, right?"], [152.92, 159.16, "You get to lead differently, and that starts with you."], [159.16, 167.4, "Because when you show up as your healthiest, most resilient, aligned self, that's where"], [167.4, 172.8, "you don't only perform better, that's where the real change starts to happen."], [172.8, 178.04, "I'm Raelle Graber, and I am so honored and excited to be here with you as a founding"], [178.04, 181.32, "Athletor Pro inside of Athletorship and MVP Accelerator."], [181.32, 185.88, "I can't wait to help you create sustainable wellness and unlock your next level."], [185.88, 186.6, "I'll see you inside."]], "pro_sagar": [[0.0, 10.6, "Hi, I'm Sagar Pandya."], [10.6, 12.84, "A few years ago, I was running"], [12.84, 15.88, "my IT and cybersecurity consulting company."], [15.88, 19.76, "Things were stable until suddenly they weren't."], [19.76, 23.36, "Overnight, every client conversation shifted."], [23.36, 27.56, "It went from how do we stay secure to,"], [27.56, 30.28, "what are we supposed to do with AI?"], [30.28, 34.14, "Internally, my team was feeling the weight too."], [34.14, 36.76, "Uncertainty, confusion."], [36.76, 38.44, "There was no roadmap,"], [38.44, 40.24, "no expert to lean on."], [40.24, 42.64, "But everyone kept looking at me,"], [42.64, 44.96, "hoping that I had the answers."], [44.96, 47.2, "That's when I realized something."], [47.2, 48.84, "I couldn't fake it."], [48.84, 53.04, "I couldn't lead from a place of control or ego."], [53.04, 57.28, "I had to shift from knowing to listening."], [57.28, 60.24, "From managing pressure to moving"], [60.24, 63.0, "through it with my team by my side."], [63.0, 66.24, "So I stopped trying to lead the conversation,"], [66.24, 69.8, "and instead started creating space for it."], [69.8, 72.16, "I brought my team together."], [72.16, 75.84, "We didn't talk tech, we talked mission."], [75.84, 78.2, "What's all of our role in this?"], [78.2, 80.0, "What do we believe in,"], [80.0, 82.2, "even if things get chaotic?"], [82.2, 84.84, "That was a start of real alignment,"], [85.28, 89.56, "and that clarity gave us permission to try,"], [89.56, 92.4, "to experiment, to ask."], [92.4, 94.64, "That's when agility showed up."], [94.64, 98.12, "Not in speed, but in shared momentum."], [98.12, 100.24, "So here's what I'll tell you."], [100.24, 103.68, "If you're leading a team through change right now,"], [103.68, 106.48, "you don't need to be the smartest voice in the room."], [106.48, 108.64, "You need to be the clearest."], [108.64, 113.04, "Alignment starts with pausing and asking"], [113.04, 116.0, "what matters to us in this moment."], [116.0, 119.04, "And agility follows when you give your team permission"], [119.04, 121.64, "to grow, not just perform."], [122.6, 124.68, "So here's your challenge."], [124.68, 127.8, "This week, take 15 minutes with your team."], [128.72, 132.08, "Don't talk metrics, but just ask one question."], [133.12, 135.92, "What's our mission right now in this season?"], [137.08, 138.24, "And then just listen."], [139.24, 144.24, "Because leadership in flow isn't about moving fast."], [144.68, 147.36, "It's about getting clear together."]], "pro_stephanie": [[0.0, 13.76, "Hi, I'm Stephanie Johnson, and if there's one thing I've learned over the years, it's"], [13.76, 14.76, "this."], [14.76, 18.72, "Leadership is forged in motion, often under pressure."], [18.72, 23.44, "A few years ago, I stepped into a new leadership role at a company in real trouble."], [23.44, 28.08, "Static revenue, unclear priorities, a team that was surviving instead of thriving."], [28.08, 33.84, "The instinct in moments like this is to take control, make big declarations, and move fast."], [33.84, 36.68, "But I didn't show up swinging a hammer of authority."], [36.68, 38.8, "I led with a different rhythm."], [38.8, 42.96, "Listen first, align fast, and adapt boldly."], [42.96, 48.1, "Listening first meant slowing down long enough to understand what wasn't being said."], [48.1, 52.32, "To hear the tension behind the silence, the exhaustion behind the surface, I met with"], [52.32, 57.72, "team members one-on-one, learning their stories, their frustrations, and their hopes."], [57.72, 61.1, "Playing fast meant finding the common thread of the chaos, a shared sense of purpose we"], [61.1, 63.24, "could all rally around."], [63.24, 65.56, "We don't have time for a drawn-out reset."], [65.56, 68.84, "We needed clarity, and we needed it quickly."], [68.84, 74.16, "Adapting boldly meant not being afraid to pivot, to experiment, to fail fast and learn"], [74.16, 75.16, "faster."], [75.16, 79.16, "I've never been afraid of change, and I'm not afraid of failure because both are essential"], [79.16, 80.82, "to transformation."], [80.82, 83.54, "That mindset became our way forward."], [83.54, 85.68, "Not perfect, but present."], [85.68, 87.48, "Not rigid, but rooted."], [87.48, 92.92, "And it's what allowed us to move from barely surviving to intentionally thriving."], [92.92, 97.32, "As we peeled back the layers, we discovered what truly motivated each person."], [97.32, 102.12, "Not just their job titles, but what is their story?"], [102.12, 103.56, "Who are their families?"], [103.56, 104.88, "What are their fears?"], [104.88, 105.88, "What are their dreams?"], [105.88, 110.22, "And in that messy human space, something clicked."], [110.22, 112.4, "We started flowing as a team."], [112.4, 116.28, "Not because we had all the answers, but because we had a shared alignment and trust."], [116.76, 119.32, "Here's where the real power showed up."], [119.32, 125.64, "I made the choice to bring my whole self to work every day, even on the tough days."], [125.64, 130.48, "I gave myself permission to lead with authenticity, and in doing so, I gave others permission"], [130.48, 132.04, "to do the same."], [132.04, 134.68, "And that's when the magic really, really started happening."], [134.68, 139.64, "Not performative magic, not perfection magic, just real."], [139.64, 142.64, "And in real is power."], [142.64, 144.96, "Here's what I've learned from Team Flow."], [144.96, 147.68, "Flow doesn't happen when everyone's doing the same thing."], [147.68, 152.2, "Flow happens when everyone is doing the right thing in harmony."], [152.2, 156.04, "Alignment isn't about forcing agreement, it's about creating clarity."], [156.04, 160.96, "Agility isn't about chaos, it's about responsiveness noted in shared purpose."], [160.96, 164.96, "But none of that is sustainable unless people feel safe to show up as they are."], [164.96, 173.48, "So many leaders think power comes from control, but real power, real power comes from authenticity."], [173.48, 177.84, "From owning who you are and creating space for others to do the same."], [177.84, 181.48, "That's what unlocks trust, that's what builds resilient teams, and that's what gets you"], [181.48, 183.8, "from resistance to flow."], [183.8, 185.12, "So here's my challenge to you."], [185.12, 191.2, "When pressure hits, and it will, don't tighten your grip, loosen it, pause, ask your team"], [191.2, 197.06, "about their why, lead with curiosity, not control, and instead of trying to direct every"], [197.06, 202.36, "single thing in every move, build alignment around the purpose, and let that alignment"], [202.44, 204.28, "be the fuel for agility."], [204.28, 209.24, "Show up as yourself every day, especially on the hard days, and be the kind of leader"], [209.24, 212.04, "who gives others the freedom to do the same."], [212.04, 216.64, "That is the heartbeat of high performing, human first teams."], [216.64, 222.6, "Team flow is not accidental, it's intentional, it's relational, and it's real, and it starts"], [222.6, 225.44, "with you leading from within."], [225.44, 229.88, "Let's change the way the world sees leadership, starting with how you see yourself."]], "pro_tracey": [[0.0, 14.92, "I will never forget this moment."], [14.92, 20.64, "A major outage had occurred for a technology company where I was responsible for all of"], [20.64, 21.92, "revenue."], [21.92, 28.48, "I was new to the company, and we had impacted some of the biggest companies on the planet"], [28.48, 33.2, "where they were not able to do business as promised."], [33.2, 35.04, "Everyone was scrambling."], [35.04, 37.2, "No one had a solution."], [37.2, 40.88, "And I was on vacation with my family."], [40.88, 43.16, "Here's what I learned about myself."], [43.16, 49.58, "When life gets difficult, it can be tempting to hide, to shrink, or even to just avoid"], [49.58, 52.36, "the situation, to delegate."], [52.36, 54.12, "That's not what I did."], [54.12, 56.76, "And that's not what you should do either."], [56.76, 61.38, "This crisis was one of those moments where showing up really mattered."], [61.38, 67.28, "And so I did, from a hotel room, on calls I didn't plan to take, while my family waited"], [67.28, 70.36, "and eventually had to go on without me."], [70.36, 73.56, "Not because I had the answers, I really didn't."], [73.56, 78.96, "I found myself hosting hourly calls with my teams, trying to create some kind of rhythm"], [78.96, 82.44, "and order at a time of great uncertainty."], [82.44, 91.36, "Our customers were rightfully upset, and our teams were so nervous and needed help."], [91.36, 95.64, "Everyone needs to know at these times that someone is paying attention."], [95.64, 99.96, "That we were going to keep moving forward one step at a time, even if we didn't have"], [99.96, 101.76, "it all figured out."], [101.76, 106.9, "We worked around the clock, and eventually everything was back to normal."], [106.9, 108.56, "We got through it."], [108.56, 113.18, "What I found so interesting about the outcome of the entire event is that we built stronger"], [113.18, 119.24, "relationships with our clients than ever before as a result of the incident."], [119.24, 123.72, "We earned their trust by showing up when it mattered most."], [123.72, 130.36, "And here's the lesson I want you to take with you as you embark on your 90-day journey."], [130.36, 135.62, "In life, things will go wrong, and when they do, people will want answers."], [135.62, 142.3, "But if you can't give concrete answers, they expect you at a minimum to remain accessible"], [142.3, 144.5, "and visible."], [144.5, 147.82, "Consistent communication will never be more important."], [147.82, 153.1, "And at the end of the day, most people understand that issues will come up."], [153.1, 157.38, "Every person and every company will have issues at some point."], [157.38, 163.74, "How you show up in those times makes all the difference, and it's what defines you as a"], [163.74, 165.06, "leader."], [165.06, 172.7, "Being agile and resilient will never be more important when you're facing big challenges."], [172.7, 175.84, "So here's my question for you."], [175.84, 178.86, "How will you show up in times of uncertainty?"]], "welcome": [[0.36, 2.2, "Welcome to the arena."], [2.2, 4.44, "This isn't just a platform,"], [4.44, 8.24, "it's your starting line for a new kind of leadership,"], [8.24, 11.48, "built from within, conditioned to win."], [11.48, 14.16, "Here, you're not just joining a course,"], [14.16, 18.96, "you're stepping into a system, a movement, a mindset."], [18.96, 22.66, "Inside this space, you'll find the M.V.P. Accelerator."], [23.58, 25.52, "Our foundational experience,"], [25.52, 28.08, "alongside other high-impact programs,"], [28.08, 30.0, "will continue to release."], [30.0, 34.44, "But first, let's talk about who you are here."], [34.44, 36.88, "You're not here because of a title."], [36.88, 40.12, "You're not here because of a position."], [40.12, 43.52, "You're here because you believe there's more,"], [43.52, 46.84, "and you're willing to do the work to unlock it."], [46.84, 49.08, "You're not simply a participant."], [49.08, 51.48, "We call you an Athleader."], [51.48, 55.16, "An Athleader is someone who leads like the elite perform,"], [55.16, 57.36, "resilient under pressure,"], [57.4, 62.0, "clear in purpose, built for the long game."], [62.0, 65.22, "And for those of you who are managers in your role,"], [65.22, 68.6, "you're not just a bystander supporting your participant."], [68.6, 72.56, "You're a Player-Coach, responsible for leading yourself"], [72.56, 75.48, "and influencing those around you."], [75.48, 78.82, "This is your locker room moment."], [78.82, 83.34, "Where you'll prepare, reflect, and commit."], [83.34, 85.32, "Because leadership isn't a position,"], [85.36, 88.32, "it's a daily practice."], [88.32, 91.08, "Why is the lion a symbol for leadership?"], [91.08, 94.04, "Not because it's the biggest or the strongest,"], [94.04, 96.44, "but because of its mindset."], [96.44, 101.24, "That's what we're building here, mental muscle memory."], [101.24, 103.56, "We condition across A.R.A.W."], [103.56, 105.48, "It's what we call the Core 4."], [105.48, 109.72, "It's agility, resilience, alignment, and wellbeing,"], [109.72, 113.22, "grounded in neuroscience and performance psychology"], [113.22, 117.3, "to shape identity that endures under pressure."], [117.3, 120.62, "You will track your momentum, know your metrics."], [120.62, 122.94, "You'll see how far you've come"], [122.94, 125.14, "and where you can still grow."], [125.14, 128.22, "Know this, you're not alone."], [128.22, 129.82, "You're a part of a team."], [129.82, 131.86, "You'll be connected to your squad,"], [131.86, 135.78, "extended M.V.P. community, and accountability partner."], [135.78, 138.54, "You will learn from other Athleader Pros,"], [138.54, 142.18, "share your voice, and celebrate progress together."], [142.18, 143.54, "So what's next?"], [143.54, 146.98, "Go through your step-by-step actions to get started."], [146.98, 150.48, "Lace up, lock in, let's go."], [150.48, 152.44, "This is your arena."], [152.44, 154.4, "This is your time."], [154.4, 156.34, "Let's win from within."]]};
